Import ListNotations.
Open Scope Z_scope.

Section RgbLib.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure} {LL : LeptLayout}.
Context {PINS : LeptPins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

Inductive winside (lo hi : Z) (M : word -> option byte) : (word -> option byte) -> Prop :=
| wi_refl : winside lo hi M M
| wi_step : forall (M' : word -> option byte) (a : word) (bs : list byte),
    winside lo hi M M' -> lo <= u a -> u a + Z.of_nat (length bs) <= hi -> winside lo hi M (wbytes M' a bs).

Lemma winside_trans : forall lo hi M1 M2 M3, winside lo hi M1 M2 -> winside lo hi M2 M3 -> winside lo hi M1 M3.
Proof.
ltac2:(KReplay.run1 (kr_t_LeptRgbLib ()) ["RgbLib"] "h03H23h12M3h21Hh32H0h43H12h59IHwinsideh62M'h72M1h82M2h91ah:2bsh;2hih<2lop;1p;4p;2p;9p;8g0000j10Tg000Uj15Tg0013j12Tg001Vj16Tg0028j41Tg003Bj1<Tg003bj24Tg004Lj23Tg004hj2;Tg005Hj1:Tg005hj27Tg006El98Tg007Oj89Tg008[R0g0099#0#0#0R1#0#0#0#5R2#2R3%51#2R1#6[R4f4R5f3R6f2R7f1R8C1f5R9P5P7P8C1f6R:P9P6f7P:P9f0R;C1X14P8%<1f9R<f8R=P:P7C1f:P<P=P6C1f;R=1426'314251;16#:'7/3=f=f<P=P:P9P5P7P8P;M98W3W2W5W0W:X93X64P7P;G9W0W4X14X84W7X;0W<o"). Qed.

