(* [comment removed for export] *)
Lemma xor3c_in_raster : forall datas wpl h r j c, datas mod 4 = 0 -> 0 <= wpl -> 0 <= r < h -> 0 <= j < wpl -> 0 <= c <= 3 -> 0 <= datas ->
  datas + 4 * wpl * r <= (datas + 4 * wpl * r + 4 * j + c) - (datas + 4 * wpl * r + 4 * j + c) mod 4 + (3 - (datas + 4 * wpl * r + 4 * j + c) mod 4) /\
  (datas + 4 * wpl * r + 4 * j + c) - (datas + 4 * wpl * r + 4 * j + c) mod 4 + (3 - (datas + 4 * wpl * r + 4 * j + c) mod 4) + 1 <= datas + 4 * wpl * r + 4 * wpl.
Proof.
